    @Test
    void leve3Pague2Com6ItemsSomaDescontoCorretamente() throws CheckoutException {
        RequisicaoCheckout requisicao = criarRequisicao(
            Collections.singletonList(
                new Item("Produto", 100.0, 6, 0.5)
            ),
            "RETIRADA_LOJA",
            "LEVE3PAGUE2",
            "PIX",
            1
        );

